INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V803','SIT803','P1','suon_se','tuy_y',NULL,'课后同学之间一对一拆解难点、互相讲题是高校主流互助学习方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_01','V803','阮明',1,'今天课上老师讲的几个贸易专业术语，我完全没理解含义啊。','jīn tiān kè shàng lǎo shī jiǎng de jǐ gè mào yì zhuān yè shù yǔ， wǒ wán quán méi lǐ jiě hán yì a。','Hôm nay mấy thuật ngữ chuyên ngành thương mại thầy giảng trên lớp, mình chẳng hiểu gì luôn ấy.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_02','V803','苏雯',2,'这几个词是国内外贸常用词汇，我举简单例子给你拆解意思。','zhè jǐ gè cí shì guó nèi wài mào cháng yòng cí huì， wǒ jǔ jiǎn dān lì zi gěi nǐ chāi jiě yì si。','Mấy từ này là từ vựng ngoại thương thông dụng trong và ngoài nước đó, mình lấy ví dụ đơn giản giải thích cho bạn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_03','V803','阮明',3,'每个词汇搭配例句讲一遍，我才能分清使用场景对吧？','měi gè cí huì dā pèi lì jù jiǎng yī biàn， wǒ cái néng fēn qīng shǐ yòng chǎng jǐng duì ba？','Mỗi từ phải kèm câu ví dụ giảng lại thì mình mới phân biệt được cách dùng đúng không ta?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_04','V803','苏雯',4,'没错，我结合课本习题举例，方便你区分易混淆词汇。','méi cuò， wǒ jié hé kè běn xí tí jǔ lì， fāng biàn nǐ qū fēn yì hùn xiáo cí huì。','Đúng rồi, mình sẽ lấy ví dụ từ bài tập trong sách, cho bạn dễ phân biệt mấy từ dễ nhầm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_05','V803','阮明',5,'耽误你半小时休息时间，实在不好意思麻烦你。','dān wù nǐ bàn xiǎo shí xiū xī shí jiān， shí zài bù hǎo yì sī má fán nǐ。','Làm mất nửa tiếng nghỉ ngơi của bạn rồi, thật ngại quá đi mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_06','V803','苏雯',6,'互相讲题很正常，之后我有语言难题也会找你帮忙。','hù xiāng jiǎng tí hěn zhèng cháng， zhī hòu wǒ yǒu yǔ yán nán tí yě huì zhǎo nǐ bāng máng。','Giảng bài qua lại cho nhau là chuyện bình thường mà, sau này mình gặp khó về ngôn ngữ cũng sẽ nhờ bạn giúp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_07','V803','阮明',7,'太感谢，听完讲解一下子清晰多了。','tài gǎn xiè， tīng wán jiǎng jiě yī xià zi qīng xī duō le。','Cảm ơn bạn nhiều ghê, nghe bạn giảng xong là thấy rõ ràng hẳn ra luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT804','SHT1','咨询老师课程平时分构成：出勤、课堂发言、小测占比',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V804','SIT804','P1','suon_se','ban_chinh_thuc',NULL,'国内大学课程普遍实行平时分+期末试卷综合打分，不会仅凭一次期末成绩定总分，鼓励日常课堂参与。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_01','V804','阮明',1,'老师，想向您咨询这门课期末总评分数的分配标准。','lǎo shī， xiǎng xiàng nín zī xún zhè mén kè qī mò zǒng píng fēn shù de fēn pèi biāo zhǔn。','Thầy ơi, em muốn hỏi thầy về cách phân bổ điểm tổng kết cuối kỳ của môn này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_02','V804','李老师',2,'总评由三部分组成：出勤20%、课堂发言与随堂小测30%、期末试卷50%哦。','zǒng píng yóu sān bù fèn zǔ chéng： chū qín 20%、 kè táng fā yán yǔ suí táng xiǎo cè 30%、 qī mò shì juàn 50% ó。','Điểm tổng kết gồm ba phần: điểm danh 20%, phát biểu trên lớp cùng kiểm tra nhỏ 30%, bài thi cuối kỳ 50% đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_03','V804','阮明',3,'随堂小测每节课都会有吗，缺课一次会直接扣掉出勤分？','suí táng xiǎo cè měi jié kè dōu huì yǒu ma， quē kè yī cì huì zhí jiē kòu diào chū qín fēn？','Kiểm tra nhỏ trên lớp buổi nào cũng có ạ, nghỉ học một buổi là bị trừ thẳng điểm chuyên cần luôn ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_04','V804','李老师',4,'无故缺课单次扣5分，请假备案不扣分；小测每月一次，错过可补。','wú gù quē kè dān cì kòu 5 fēn， qǐng jià bèi àn bù kòu fēn； xiǎo cè měi yuè yī cì， cuò guò kě bǔ。','Nghỉ không phép một lần trừ 5 điểm, còn xin phép có ghi nhận thì không trừ; kiểm tra nhỏ mỗi tháng một lần, lỡ thì được thi bù.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_05','V804','阮明',5,'课堂发言只要主动回答问题，就能拿到对应的平时分吗？','kè táng fā yán zhǐ yào zhǔ dòng huí dá wèn tí， jiù néng ná dào duì yìng de píng shí fēn ma？','Chỉ cần chủ động phát biểu trả lời câu hỏi là được tính điểm chuyên cần tương ứng đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_06','V804','李老师',6,'主动思考作答、有完整观点，都会记录课堂表现分。','zhǔ dòng sī kǎo zuò dá、 yǒu wán zhěng guān diǎn， dōu huì jì lù kè táng biǎo xiàn fēn。','Chỉ cần chủ động suy nghĩ trả lời, có quan điểm rõ ràng, đều sẽ được ghi nhận vào điểm thể hiện trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_07','V804','阮明',7,'我清楚分值规则了，之后多主动参与课堂互动。','wǒ qīng chǔ fēn zhí guī zé le， zhī hòu duō zhǔ dòng cān yù kè táng hù dòng。','Em hiểu rõ quy tắc tính điểm rồi ạ, sau này em sẽ tích cực tham gia phát biểu trên lớp hơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT805','SHT1','忘记带课本，和同桌共用一本书听课',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V805','SIT805','P1','twist','tuy_y',NULL,'课堂忘记带教材和同桌共用书本很常见，但不建议长期如此，会影响双方记笔记效率。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_01','V805','阮明',1,'糟糕，早上出门匆忙，把专业课课本落在宿舍了，能和你共用一本吗？','zāo gāo， zǎo shàng chū mén cōng máng， bǎ zhuān yè kè kè běn luò zài sù shè le， néng hé nǐ gòng yòng yī běn ma？','Chết rồi, sáng nay vội quá nên bỏ quên sách chuyên ngành ở ký túc xá, dùng chung sách với cậu được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_02','V805','小林',2,'可以一起看，不过书本放在中间，记笔记会有点挤不方便。','kě yǐ yì qǐ kàn， bù guò shū běn fàng zài zhōng jiān， jì bǐ jì huì yǒu diǎn jǐ bù fāng biàn。','Xem chung cũng được, nhưng để sách ở giữa thì ghi chép sẽ hơi chật, bất tiện đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_03','V805','阮明',3,'我只对照书页听讲解，笔记先记在草稿纸上，下课再整理。','wǒ zhǐ duì zhào shū yè tīng jiǎng jiě， bǐ jì xiān jì zài cǎo gǎo zhǐ shàng， xià kè zài zhěng lǐ。','Mình chỉ nhìn theo trang sách nghe giảng thôi, ghi chú thì mình ghi ra giấy nháp trước, hết tiết rồi chép lại sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_04','V805','小林',4,'老师等下要勾画重点段落，我们分开两边各自标注会不会混乱嘛。','lǎo shī děng xià yào gōu huà zhòng diǎn duàn luò， wǒ men fēn kāi liǎng biān gè zì biāo zhù huì bú huì hùn luàn ma。','Lát nữa thầy sẽ gạch chân mấy đoạn trọng tâm, mình mỗi người để một bên tự đánh dấu vậy có lộn xộn không ta.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_05','V805','阮明',5,'我手机拍课本页面，重点自己在照片上标记，不影响你看书。','wǒ shǒu jī pāi kè běn yè miàn， zhòng diǎn zì jǐ zài zhào piān shàng biāo jì， bù yǐng xiǎng nǐ kàn shū。','Mình chụp lại trang sách bằng điện thoại, chỗ nào quan trọng tự đánh dấu trên ảnh, không ảnh hưởng đến cậu xem sách đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_06','V805','小林',6,'这样也行，有看不懂的段落随时指给我一起讨论。','zhè yàng yě xíng， yǒu kàn bù dǒng de duàn luò suí shí zhǐ gěi wǒ yì qǐ tǎo lùn。','Vậy cũng được, đoạn nào không hiểu thì cứ chỉ cho mình xem rồi cùng bàn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_07','V805','阮明',7,'今天多亏你，不然整节课没法跟上老师进度。','jīn tiān duō kuī nǐ， bù rán zhěng jié kè méi fǎ gēn shàng lǎo shī jìn dù。','Hôm nay may có cậu giúp, không thì cả tiết học mình theo không kịp tiến độ của thầy mất.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT806','SHT1','上课手机静音没做到，被老师提醒课堂纪律',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V806','SIT806','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂严格管控手机声响，震动、响铃都会被老师提醒，多次违规会扣除课堂表现分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_01','V806','阮明',1,'老师对不起，刚刚手机消息突然响铃，打断您讲课了。','lǎo shī duì bù qǐ， gāng gāng shǒu jī xiāo xī tū rán xiǎng líng， dǎ duàn nín jiǎng kè le。','Thầy ơi em xin lỗi, vừa nãy điện thoại em tự nhiên reo, làm gián đoạn bài giảng của thầy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_02','V806','李老师',2,'课堂要求所有手机必须完全静音或关机，你忘记调整设置了？','kè táng yāo qiú suǒ yǒu shǒu jī bì xū wán quán jìng yīn huò guān jī， nǐ wàng jì tiáo zhěng shè zhì le？','Trên lớp yêu cầu tất cả điện thoại phải để im lặng hoàn toàn hoặc tắt máy, em quên chỉnh lại à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_03','V806','阮明',3,'早上调了震动，没想到震动声响也很明显，干扰全班听课嘛。','zǎo shàng diào le zhèn dòng， méi xiǎng dào zhèn dòng shēng xiǎng yě hěn míng xiǎn， gān rǎo quán bān tīng kè ma。','Sáng nay em để chế độ rung, không ngờ tiếng rung cũng khá rõ, làm ảnh hưởng đến cả lớp nghe giảng luôn ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_04','V806','李老师',4,'一次警告不计入扣分，之后如果再出现声响会扣除课堂平时分。','yī cì jǐng gào bù jì rù kòu fēn， zhī hòu rú guǒ zài chū xiàn shēng xiǎng huì kòu chú kè táng píng shí fēn。','Lần này nhắc nhở thôi không tính trừ điểm, sau này nếu còn xảy ra tiếng động sẽ bị trừ vào điểm chuyên cần đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_05','V806','阮明',5,'我现在直接关机，整节课不再开启手机接收消息。','wǒ xiàn zài zhí jiē guān jī， zhěng jié kè bù zài kāi qǐ shǒu jī jiē shōu xiāo xī。','Em tắt máy luôn bây giờ ạ, cả tiết học em sẽ không mở điện thoại nhận tin nhắn nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_06','V806','李老师',6,'课堂需要安静的听讲环境，还请遵守班级课堂规定。','kè táng xū yào ān jìng de tīng jiǎng huán jìng， hái qǐng zūn shǒu bān jí kè táng guī dìng。','Lớp học cần môi trường yên tĩnh để nghe giảng, mong em tuân thủ quy định của lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_07','V806','阮明',7,'我记住教训，之后课前一定检查手机静音状态。','wǒ jì zhù jiào xùn， zhī hòu kè qián yí dìng jiǎn chá shǒu jī jìng yīn zhuàng tài。','Em ghi nhớ bài học này rồi ạ, sau này trước giờ học em sẽ luôn kiểm tra điện thoại đã để im lặng chưa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT807','SHT1','咨询课程课外拓展阅读书目、图书馆馆藏位置',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V807','SIT807','P1','suon_se','ban_chinh_thuc',NULL,'大学专业课会配套拓展阅读书目，图书馆专业馆藏区集中存放对应书籍，支持学生课外自主拓展学习。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_01','V807','阮明',1,'老师，想提升专业水平，请问这门课配套拓展阅读书籍有哪些？','lǎo shī， xiǎng tí shēng zhuān yè shuǐ píng， qǐng wèn zhè mén kè pèi tào tuò zhǎn yuè dú shū jí yǒu nǎ xiē？','Thầy ơi, em muốn nâng cao trình độ chuyên môn, cho em hỏi môn này có những sách đọc mở rộng nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_02','V807','李老师',2,'我列三本核心参考书，全部存放在图书馆三楼外文专业区哦。','wǒ liè sān běn hé xīn cān kǎo shū， quán bù cún fàng zài tú shū guǎn sān lóu wài wén zhuān yè qū ó。','Thầy liệt kê ba cuốn sách tham khảo cốt lõi, tất cả đều để ở khu chuyên ngành ngoại văn tầng ba thư viện đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_03','V807','阮明',3,'这几本书可以外借带回家长期阅读，还是只能馆内阅览？','zhè jǐ běn shū kě yǐ wài jiè dài huí jiā zhǎng qī yuè dú， hái shì zhǐ néng guǎn nèi yuè lǎn？','Mấy cuốn sách này có thể mượn về nhà đọc lâu dài không ạ, hay chỉ đọc tại thư viện thôi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_04','V807','李老师',4,'均可借阅三十天，线上系统还能办理续借延长阅读时间。','jūn kě jiè yuè sān shí tiān， xiàn shàng xì tǒng hái néng bàn lǐ xù jiè yán cháng yuè dú shí jiān。','Đều mượn được ba mươi ngày, hệ thống trực tuyến còn có thể gia hạn thêm thời gian đọc nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_05','V807','阮明',5,'我记下书名，下课直接去图书馆检索借阅。','wǒ jì xià shū míng， xià kè zhí jiē qù tú shū guǎn jiǎn suǒ jiè yuè。','Em ghi lại tên sách rồi ạ, hết tiết em sẽ ra thư viện tra cứu mượn luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_06','V807','李老师',6,'阅读完有疑问，随时来办公室和我交流书中观点。','yuè dú wán yǒu yí wèn， suí shí lái bàn gōng shì hé wǒ jiāo liú shū zhōng guān diǎn。','Đọc xong có gì thắc mắc, cứ lên văn phòng trao đổi với thầy về nội dung sách nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_07','V807','阮明',7,'感谢老师推荐书目，对我的专业学习帮助很大。','gǎn xiè lǎo shī tuī jiàn shū mù， duì wǒ de zhuān yè xué xí bāng zhù hěn dà。','Em cảm ơn thầy đã giới thiệu sách, giúp ích rất nhiều cho việc học chuyên ngành của em ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT808','SHT1','小组讨论时观点分歧，和组员温和协商统一思路',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V808','SIT808','P1','suon_se','tuy_y',NULL,'国内小组作业鼓励充分发表不同观点，通过讨论、分工、投票协商统一方案，不强行听从单一人员想法。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_01','V808','阮明',1,'我对小组报告案例选取有不同想法，和大家现在选定的方向不一样。','wǒ duì xiǎo zǔ bào gào àn lì xuǎn qǔ yǒu bù tóng xiǎng fǎ， hé dà jiā xiàn zài xuǎn dìng de fāng xiàng bù yí yàng。','Mình có ý kiến khác về việc chọn case cho bài báo cáo nhóm, khác với hướng mà mọi người đang chọn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_02','V808','苏雯',2,'你说说你的思路，我们一起对比两个方案的优劣再做决定。','nǐ shuō shuō nǐ de sī lù， wǒ men yì qǐ duì bǐ liǎng gè fāng àn de yōu liè zài zuò jué dìng。','Cậu nói thử hướng của cậu xem, tụi mình so sánh ưu nhược điểm của hai phương án rồi quyết định luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_03','V808','阮明',3,'我选的案例数据更贴近留学生视角，更容易结合我们课堂所学。','wǒ xuǎn de àn lì shù jù gèng tiē jìn liú xué shēng shì jiǎo， gèng róng yì jié hé wǒ men kè táng suǒ xué。','Case mình chọn có dữ liệu sát với góc nhìn của du học sinh hơn, dễ gắn với kiến thức đã học trên lớp hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_04','V808','苏雯',4,'原有案例优势是资料充足，你的案例需要额外查找外文资料嘛。','yuán yǒu àn lì yōu shì shì zī liào chōng zú， nǐ de àn lì xū yào é wài chá zhǎo wài wén zī liào ma。','Case cũ có ưu điểm là tài liệu đầy đủ sẵn rồi, còn case của cậu chắc phải tìm thêm tài liệu nước ngoài đó nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_05','V808','阮明',5,'我可以负责全部外文资料检索，分担小组搜集素材的工作量。','wǒ kě yǐ fù zé quán bù wài wén zī liào jiǎn suǒ， fēn dān xiǎo zǔ sōu jí sù cái de gōng zuò liàng。','Mình có thể nhận luôn phần tra cứu hết tài liệu nước ngoài, san sẻ bớt khối lượng thu thập tư liệu cho nhóm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_06','V808','苏雯',6,'那我们投票，多数人认可你的方案就调整报告选题。','nà wǒ men tóu piào， duō shù rén rèn kě nǐ de fāng àn jiù tiáo zhěng bào gào xuǎn tí。','Vậy tụi mình biểu quyết đi, nếu đa số đồng ý phương án của cậu thì đổi đề tài báo cáo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_07','V808','阮明',7,'谢谢大家愿意一起讨论，综合所有人想法完善作业。','xiè xiè dà jiā yuàn yì yì qǐ tǎo lùn， zōng hé suǒ yǒu rén xiǎng fǎ wán shàn zuò yè。','Cảm ơn mọi người đã chịu bàn bạc cùng nhau, tổng hợp ý kiến của tất cả để bài làm hoàn thiện hơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT809','SHT1','询问老师课堂发言加分规则，主动争取平时分',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V809','SIT809','P1','suon_se','ban_chinh_thuc',NULL,'大学课堂鼓励学生主动发言提问，以此折算平时分，平衡期末试卷单一考核的局限性。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_01','V809','阮明',1,'老师，想咨询课堂发言加分的详细规则，我想多争取平时表现分。','lǎo shī， xiǎng zī xún kè táng fā yán jiā fēn de xiáng xì guī zé， wǒ xiǎng duō zhēng qǔ píng shí biǎo xiàn fēn。','Thưa cô, em muốn hỏi rõ quy định cộng điểm khi phát biểu trên lớp, em muốn cố gắng lấy thêm điểm chuyên cần ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_02','V809','李老师',2,'主动举手回答、提出有价值疑问、上台简短分享，都能累加课堂分。','zhǔ dòng jǔ shǒu huí dá、 tí chū yǒu jià zhí yí wèn、 shàng tái jiǎn duǎn fēn xiǎng， dōu néng lěi jiā kè táng fēn。','Chủ động giơ tay trả lời, đặt câu hỏi có giá trị, hay lên bảng chia sẻ ngắn gọn, tất cả đều được cộng điểm chuyên cần nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_03','V809','阮明',3,'每次发言加分分值相同，还是完整长篇回答分值更高？','měi cì fā yán jiā fēn fēn zhí xiāng tóng， hái shì wán zhěng cháng piān huí dá fēn zhí gèng gāo？','Mỗi lần phát biểu điểm cộng có bằng nhau không ạ, hay trả lời đầy đủ, dài hơn thì điểm cao hơn?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_04','V809','李老师',4,'不看长短，只要独立思考、贴合课堂主题，每次统一加2分。','bù kàn cháng duǎn， zhǐ yào dú lì sī kǎo、 tiē hé kè táng zhǔ tí， měi cì tǒng yī jiā 2 fēn。','Không tính theo độ dài đâu, chỉ cần suy nghĩ độc lập và bám sát chủ đề bài học, mỗi lần đều cộng đều 2 điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_05','V809','阮明',5,'每节课最多能几次发言，有没有单次课堂加分上限？','měi jié kè zuì duō néng jǐ cì fā yán， yǒu méi yǒu dān cì kè táng jiā fēn shàng xiàn？','Mỗi tiết học tối đa được phát biểu mấy lần ạ, có giới hạn điểm cộng cho một buổi học không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_06','V809','李老师',6,'无次数上限，只要不占用过多课堂时间均可主动发言。','wú cì shù shàng xiàn， zhǐ yào bù zhàn yòng guò duō kè táng shí jiān jūn kě zhǔ dòng fā yán。','Không giới hạn số lần, miễn là không chiếm quá nhiều thời gian lớp học thì cứ chủ động phát biểu thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_07','V809','阮明',7,'之后每节课我主动思考提问、回答，积极参与课堂互动。','zhī hòu měi jié kè wǒ zhǔ dòng sī kǎo tí wèn、 huí dá， jī jí cān yù kè táng hù dòng。','Từ giờ mỗi tiết học em sẽ chủ động suy nghĩ, đặt câu hỏi, trả lời, tích cực tham gia tương tác trên lớp ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT810','SHT2','论文引用格式不懂，请教专业课老师规范要求',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V810','SIT810','P1','twist','chinh_thuc',NULL,'国内高校毕业论文统一执行国家标准参考文献格式，自媒体网络内容认可度低，学术写作优先纸质期刊、专著。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_01','V810','阮明',1,'老师，毕业论文参考文献引用格式我始终把握不准，想向您请教标准。','lǎo shī， bì yè lùn wén cān kǎo wén xiàn yǐn yòng gé shì wǒ shǐ zhōng bǎ wò bù zhǔn， xiǎng xiàng nín qǐng jiào biāo zhǔn。','Thưa cô, em cứ nắm không chắc cách trình bày trích dẫn tài liệu tham khảo trong luận văn tốt nghiệp, em muốn hỏi cô về chuẩn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_02','V810','李老师',2,'校内统一使用GB/T7714国家标准格式，课件最后附完整范例。','xiào nèi tǒng yī shǐ yòng GB/T7714 guó jiā biāo zhǔn gé shì， kè jiàn zuì hòu fù wán zhěng fàn lì。','Trong trường thống nhất dùng định dạng chuẩn quốc gia GB/T7714, cuối slide bài giảng có kèm ví dụ đầy đủ rồi đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_03','V810','阮明',3,'外文书籍、期刊、网页资料三种文献格式区分很大对吗？','wài wén shū jí、 qī kān、 wǎng yè zī liào sān zhǒng wén xiàn gé shì qū fēn hěn dà duì ma？','Ba loại tài liệu sách nước ngoài, tạp chí, và trang web có khác nhau nhiều về định dạng phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_04','V810','李老师',4,'网页自媒体资源不建议大量引用，书籍、正规期刊优先使用嘛。','wǎng yè zì méi tǐ zī yuán bù jiàn yì dà liàng yǐn yòng， shū jí、 zhèng guī qī kān yōu xiān shǐ yòng ma。','Nguồn từ trang mạng, tự truyền thông thì không nên trích dẫn nhiều, ưu tiên dùng sách và tạp chí chính thống hơn nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_05','V810','阮明',5,'我按照课件范例调整格式，修改完成后能麻烦您帮忙检查一遍吗？','wǒ àn zhào kè jiàn fàn lì tiáo zhěng gé shì， xiū gǎi wán chéng hòu néng má fán nín bāng máng jiǎn chá yī biàn ma？','Em sẽ chỉnh sửa theo mẫu trong slide bài giảng, sau khi sửa xong phiền cô giúp em kiểm tra lại một lượt được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_06','V810','李老师',6,'初稿定稿前可以发我线上预览，指出格式错误再修改。','chū gǎo dìng gǎo qián kě yǐ fā wǒ xiàn shàng yù lǎn， zhǐ chū gé shì cuò wù zài xiū gǎi。','Trước khi hoàn thiện bản cuối, em có thể gửi bản online cho cô xem trước, cô sẽ chỉ ra chỗ sai để em sửa lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_07','V810','阮明',7,'谢谢您耐心指导引用规范，避免论文大量格式扣分。','xiè xiè nín nài xīn zhǐ dǎo yǐn yòng guī fàn， bì miǎn lùn wén dà liàng gé shì kòu fēn。','Cảm ơn cô đã kiên nhẫn hướng dẫn quy chuẩn trích dẫn, để luận văn tránh bị trừ điểm nhiều vì lỗi định dạng ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT811','SHT2','查重重复率超标，咨询老师降重修改方法',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V811','SIT811','P1','that_bai_nhe','ban_chinh_thuc',NULL,'高校毕业论文查重有硬性重复率阈值，复制粘贴原文会判定学术不端，必须自行转述降重。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_01','V811','阮明',1,'老师，我的初稿论文查重重复率超过30%，达不到学校合格标准。','lǎo shī， wǒ de chū gǎo lùn wén chá chóng chóng fù lǜ chāo guò 30%， dá bú dào xué xiào hé gé biāo zhǔn。','Thưa cô, bản nháp luận văn của em bị trùng lặp hơn 30% khi kiểm tra đạo văn, chưa đạt chuẩn của trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_02','V811','李老师',2,'合格重复率要求控制在20%以内，超标需要大面积改写降重。','hé gé chóng fù lǜ yāo qiú kòng zhì zài 20% yǐ nèi， chāo biāo xū yào dà miàn jī gǎi xiě jiàng zhòng。','Tỷ lệ trùng lặp đạt chuẩn phải giữ trong 20% trở xuống, vượt mức thì phải sửa lại diện rộng để giảm trùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_03','V811','阮明',3,'我只是直接摘抄文献句子，不清楚转述改写的技巧啊。','wǒ zhǐ shì zhí jiē zhāi chāo wén xiàn jù zi， bù qīng chǔ zhuǎn shù gǎi xiě de jì qiǎo a。','Em chỉ trích thẳng câu chữ từ tài liệu thôi, chưa rành kỹ thuật diễn đạt lại, viết lại theo ý mình đâu ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_04','V811','李老师',4,'不能简单替换同义词，要调整句子语序、拆分长句、补充自己的分析嘛。','bù néng jiǎn dān tì huàn tóng yì cí， yào tiáo zhěng jù zi yǔ xù、 chāi fēn cháng jù、 bǔ chōng zì jǐ de fēn xī ma。','Không thể chỉ đơn giản thay từ đồng nghĩa được, phải đảo trật tự câu, tách câu dài ra, thêm phân tích của riêng mình vào nữa.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_05','V811','阮明',5,'图表数据、公式部分会不会计入重复率，需要重新绘制吗？','tú biǎo shù jù、 gōng shì bù fèn huì bú huì jì rù chóng fù lǜ， xū yào chóng xīn huì zhì ma？','Phần biểu đồ, số liệu, công thức có bị tính vào tỷ lệ trùng lặp không ạ, có cần vẽ lại hết không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_06','V811','李老师',6,'通用公式不计入，文字分析段落必须全部重新转述改写。','tōng yòng gōng shì bù jì rù， wén zì fēn xī duàn luò bì xū quán bù chóng xīn zhuǎn shù gǎi xiě。','Công thức thông dụng thì không tính, còn đoạn phân tích chữ viết bắt buộc phải viết lại toàn bộ theo cách diễn đạt khác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_07','V811','阮明',7,'我按照您的方法逐段改写，修改完成后再次提交查重。','wǒ àn zhào nín de fāng fǎ zhú duàn gǎi xiě， xiū gǎi wán chéng hòu zài cì tí jiāo chá zhòng。','Em sẽ viết lại từng đoạn theo cách cô hướng dẫn, sửa xong sẽ nộp kiểm tra đạo văn lại lần nữa ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT812','SHT2','找不到外文参考文献，求助图书馆馆员检索外文数据库',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V812','SIT812','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆购买多语种外文数据库，仅校园内网、校园VPN可免费下载全文外文文献。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_01','V812','阮明',1,'老师，我写论文需要越南、东南亚相关外文文献，自己检索不到。','lǎo shī， wǒ xiě lùn wén xū yào yuè nán、 dōng nán yà xiāng guān wài wén wén xiàn， zì jǐ jiǎn suǒ bú dào。','Thưa cô, em viết luận văn cần tài liệu nước ngoài liên quan đến Việt Nam, Đông Nam Á, mà tự tra không ra ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_02','V812','王馆员',2,'校内开通多国外文数据库，我带你进入外文检索专属页面。','xiào nèi kāi tōng duō guó wài wén shù jù kù， wǒ dài nǐ jìn rù wài wén jiǎn suǒ zhuān shǔ yè miàn。','Trường có mở nhiều cơ sở dữ liệu ngoại văn của các nước, cô dẫn em vào trang tra cứu ngoại văn riêng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_03','V812','阮明',3,'输入关键词只能检索中文文献，需要切换语种检索入口对吧？','shū rù guān jiàn cí zhǐ néng jiǎn suǒ zhōng wén wén xiàn， xū yào qiè huàn yǔ zhǒng jiǎn suǒ rù kǒu duì ba？','Nhập từ khóa thì chỉ ra được tài liệu tiếng Trung thôi, chắc phải chuyển sang cổng tra cứu ngôn ngữ khác đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_04','V812','王馆员',4,'没错，切换外文语种后，限定地区、出版年份缩小检索范围。','méi cuò， qiè huàn wài wén yǔ zhǒng hòu， xiàn dìng dì qū、 chū bǎn nián fèn suō xiǎo jiǎn suǒ fàn wéi。','Đúng rồi, sau khi chuyển sang ngôn ngữ nước ngoài, em có thể giới hạn khu vực, năm xuất bản để thu hẹp phạm vi tìm kiếm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_05','V812','阮明',5,'检索到的外文文献可以直接下载全文PDF吗？','jiǎn suǒ dào de wài wén wén xiàn kě yǐ zhí jiē xià zài quán wén PDF ma？','Tài liệu nước ngoài tìm được có thể tải trực tiếp bản PDF đầy đủ được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_06','V812','王馆员',6,'校内IP可免费下载，校外需要登录校园网VPN访问数据库。','xiào nèi IP kě miǎn fèi xià zài， xiào wài xū yào dēng lù xiào yuán wǎng VPN fǎng wèn shù jù kù。','Dùng IP trong trường thì tải miễn phí, còn ngoài trường phải đăng nhập VPN mạng trường mới truy cập được cơ sở dữ liệu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_07','V812','阮明',7,'麻烦您带我操作一遍检索流程，之后我自己查找文献。','má fán nín dài wǒ cāo zuò yī biàn jiǎn suǒ liú chéng， zhī hòu wǒ zì jǐ chá zhǎo wén xiàn。','Phiền cô dẫn em thao tác thử một lượt quy trình tra cứu, sau đó em tự tìm tài liệu ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT813','SHT2','打印论文装订格式错误，打印店重新调整排版',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V813','SIT813','P1','twist','tuy_y',NULL,'各学院毕业论文有统一打印排版模板，页眉、行距、页边距、装订线均有硬性规范，打印店常备模板供学生使用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_01','V813','阮明',1,'你好，刚打印的毕业论文装订不对，页码、页眉格式不符合学院要求。','nǐ hǎo， gāng dǎ yìn de bì yè lùn wén zhuāng dìng bú duì， yè mǎ、 yè méi gé shì bù fú hé xué yuàn yāo qiú。','Chào anh/chị, luận văn tốt nghiệp em vừa in xong đóng gáy không đúng, số trang, phần đầu trang không đúng theo yêu cầu của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_02','V813','店员',2,'学院有统一排版模板，你刚才直接上传文档没有套用标准模板嘛。','xué yuàn yǒu tǒng yī pái bǎn mú bǎn， nǐ gāng cái zhí jiē shàng chuán wén dàng méi yǒu tào yòng biāo zhǔn mú bǎn ma。','Khoa có mẫu định dạng thống nhất, lúc nãy em tải file lên in trực tiếp mà không áp mẫu chuẩn đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_03','V813','阮明',3,'我不知道学校专用模板，直接用自己电脑里的格式导出打印了。','wǒ bù zhī dào xué xiào zhuān yòng mú bǎn， zhí jiē yòng zì jǐ diàn nǎo lǐ de gé shì dǎo chū dǎ yìn le。','Em không biết trường có mẫu riêng, cứ dùng định dạng trong máy tính của mình xuất ra in luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_04','V813','店员',4,'我现在套用学院官方模板重新调整，页眉、页码、行距全部统一修改。','wǒ xiàn zài tào yòng xué yuàn guān fāng mú bǎn chóng xīn tiáo zhěng， yè méi、 yè mǎ、 háng jù quán bù tǒng yī xiū gǎi。','Giờ mình áp mẫu chính thức của khoa chỉnh lại, phần đầu trang, số trang, giãn dòng sửa lại đồng bộ hết nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_05','V813','阮明',5,'重新排版打印会额外收取一次打印费用吗？','chóng xīn pái bǎn dǎ yìn huì é wài shōu qǔ yī cì dǎ yìn fèi yòng ma？','In lại theo định dạng mới thì có tính thêm phí in lần nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_06','V813','店员',6,'格式调整失误首次免费重打，多次修改才会叠加收费。','gé shì tiáo zhěng shī wù shǒu cì miǎn fèi zhòng dǎ， duō cì xiū gǎi cái huì dié jiā shōu fèi。','Lỗi định dạng thì lần đầu in lại miễn phí, sửa nhiều lần mới cộng dồn phí thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_07','V813','阮明',7,'辛苦重新排版，调整完我检查无误再装订成册。','xīn kǔ chóng xīn pái bǎn， tiáo zhěng wán wǒ jiǎn chá wú wù zài zhuāng dìng chéng cè。','Cảm ơn anh/chị đã dàn trang lại giúp em, chỉnh xong em kiểm tra không sai gì rồi mới đóng thành quyển.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT814','SHT2','小组论文有人拖延进度，和组员沟通制定截止时间表',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V814','SIT814','P1','suon_se','tuy_y',NULL,'国内小组作业普遍设置分段截止日期，避免临近交稿集体赶工、质量粗糙。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_01','V814','阮明',1,'距离小组论文提交只剩五天，有部分板块素材还没有收集完成。','jù lí xiǎo zǔ lùn wén tí jiāo zhǐ shèng wǔ tiān， yǒu bù fèn bǎn kuài sù cái hái méi yǒu shōu jí wán chéng。','Còn có năm ngày nữa là nộp luận văn nhóm rồi mà một số phần tư liệu vẫn chưa thu thập xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_02','V814','苏雯',2,'有两位组员进度滞后，我们统一拆分每日任务，设置分段小截止期。','yǒu liǎng wèi zǔ yuán jìn dù zhì hòu， wǒ men tǒng yī chāi fēn měi rì rèn wù， shè zhì fēn duàn xiǎo jié zhǐ qī。','Có hai bạn trong nhóm đang chậm tiến độ, tụi mình chia đều công việc từng ngày, đặt mốc hạn nhỏ từng chặng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_03','V814','小林',3,'每天晚上八点群内同步当日完成内容，避免最后一天集中赶工。','měi tiān wǎn shàng bā diǎn qún nèi tóng bù dāng rì wán chéng nèi róng， bì miǎn zuì hòu yī tiān jí zhōng gǎn gōng。','Mỗi tối tám giờ báo cáo trong nhóm phần đã hoàn thành trong ngày, tránh để dồn hết vào ngày cuối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_04','V814','阮明',4,'我负责外文文献翻译，最晚后天完成全部翻译素材交付。','wǒ fù zé wài wén wén xiàn fān yì， zuì wǎn hòu tiān wán chéng quán bù fān yì sù cái jiāo fù。','Mình phụ trách dịch tài liệu nước ngoài, chậm nhất là ngày kia sẽ hoàn thành nộp toàn bộ tư liệu dịch.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_05','V814','苏雯',5,'每人明确标注自己的分工与完成时间，逾期提前在群内说明困难。','měi rén míng què biāo zhù zì jǐ de fēn gōng yǔ wán chéng shí jiān， yú qī tí qián zài qún nèi shuō míng kùn nán。','Mỗi người ghi rõ phần việc và thời gian hoàn thành của mình, nếu trễ hẹn thì báo trước khó khăn trong nhóm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_06','V814','阮明',6,'如果有人遇到检索、写作难题，群内大家一起协助解决。','rú guǒ yǒu rén yù dào jiǎn suǒ、 xiě zuò nán tí， qún nèi dà jiā yì qǐ xié zhù jiě jué。','Nếu ai gặp khó khi tra cứu, viết bài thì cả nhóm cùng hỗ trợ giải quyết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_07','V814','小林',7,'按时间表分段推进，保证论文完整、高质量按时上交。','àn shí jiān biǎo fēn duàn tuī jìn， bǎo zhèng lùn wén wán zhěng、 gāo zhì liàng àn shí shàng jiāo。','Cứ theo lịch mà chia chặng tiến hành, đảm bảo luận văn hoàn chỉnh, chất lượng và nộp đúng hạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT815','SHT2','咨询论文致谢、摘要、关键词标准写作规范',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V815','SIT815','P1','suon_se','chinh_thuc',NULL,'国内本科毕业论文强制要求中文摘要+英文摘要、规范关键词、简短致谢，三部分有固定字数与格式标准。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_01','V815','阮明',1,'老师，想请教毕业论文摘要、关键词、致谢三段写作规范。','lǎo shī， xiǎng qǐng jiào bì yè lùn wén zhāi yào、 guān jiàn cí、 zhì xiè sān duàn xiě zuò guī fàn。','Thưa cô, em muốn hỏi quy chuẩn viết ba phần tóm tắt, từ khóa và lời cảm ơn trong luận văn tốt nghiệp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_02','V815','李老师',2,'摘要三百字以内，完整概括研究目的、方法、结论；关键词3-5个。','zhāi yào sān bǎi zì yǐ nèi， wán zhěng gài kuò yán jiū mù dì、 fāng fǎ、 jié lùn； guān jiàn cí 3-5 gè。','Tóm tắt trong khoảng ba trăm chữ, khái quát đầy đủ mục đích, phương pháp, kết luận nghiên cứu; từ khóa từ 3 đến 5 từ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_03','V815','阮明',3,'致谢部分可以感谢家人、同学、授课老师，篇幅有限制吗？','zhì xiè bù fèn kě yǐ gǎn xiè jiā rén、 tóng xué、 shòu kè lǎo shī， piān fú yǒu xiàn zhì ma？','Phần cảm ơn có thể cảm ơn gia đình, bạn học, thầy cô giảng dạy, có giới hạn độ dài không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_04','V815','李老师',4,'致谢篇幅一页以内，简洁真诚即可，不用过度冗长抒情嘛。','zhì xiè piān fú yī yè yǐ nèi， jiǎn jié zhēn chéng jí kě， bù yòng guò dù rǒng cháng shū qíng ma。','Phần cảm ơn tối đa một trang, viết ngắn gọn chân thành là được, không cần lan man cảm xúc quá dài đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_05','V815','阮明',5,'摘要需要中英文双语版本，翻译关键词也要对应准确？','zhāi yào xū yào zhōng yīng wén shuāng yǔ bǎn běn， fān yì guān jiàn cí yě yào duì yìng zhǔn què？','Tóm tắt cần có bản song ngữ Việt Trung, còn từ khóa dịch cũng phải chính xác tương ứng đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_06','V815','李老师',6,'本科毕业论文摘要中英文对照，关键词逐词精准翻译。','běn kē bì yè lùn wén zhāi yào zhōng yīng wén duì zhào， guān jiàn cí zhú cí jīng zhǔn fān yì。','Luận văn tốt nghiệp đại học tóm tắt phải đối chiếu Trung - Anh, từ khóa dịch chính xác từng từ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_07','V815','阮明',7,'我按照规范撰写三段内容，初稿写完发给您检查。','wǒ àn zhào guī fàn zhuàn xiě sān duàn nèi róng， chū gǎo xiě wán fā gěi nín jiǎn chá。','Em sẽ viết ba phần theo đúng quy chuẩn, viết xong bản nháp sẽ gửi cô kiểm tra ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT816','SHT2','电脑崩溃丢失作业初稿，向老师说明情况申请延后上交',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V816','SIT816','P1','twist','ban_chinh_thuc',NULL,'学生设备故障丢失作业属于合理客观事由，多数老师会适度放宽提交期限，但会提醒养成云端备份文件的习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_01','V816','阮明',1,'老师不好意思，昨晚电脑系统崩溃，存储的课程论文初稿全部丢失。','lǎo shī bù hǎo yì sī， zuó wǎn diàn nǎo xì tǒng bēng kuì， cún chǔ de kè chéng lùn wén chū gǎo quán bù diū shī。','Thầy ơi em xin lỗi, tối qua máy tính của em bị sập hệ thống, bản thảo tiểu luận môn học lưu trong máy mất sạch rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_02','V816','李老师',2,'有没有云端备份、U盘备份，能找回一部分写作内容吗？','yǒu méi yǒu yún duān bèi fèn、U pán bèi fèn， néng zhǎo huí yī bù fèn xiě zuò nèi róng ma？','Em không có sao lưu trên đám mây hay USB gì để lấy lại được phần nào không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_03','V816','阮明',3,'没有及时云端同步，只保留少量手写草稿，完整电子版全部丢失嘛。','méi yǒu jí shí yún duān tóng bù， zhǐ bǎo liú shǎo liàng shǒu xiě cǎo gǎo， wán zhěng diàn zi bǎn quán bù diū shī ma。','Em không kịp đồng bộ lên cloud, chỉ còn giữ được vài trang bản thảo viết tay thôi, còn bản điện tử đầy đủ thì mất hết rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_04','V816','李老师',4,'正常截止时间今天下午，突发设备故障可以延后一天提交。','zhèng cháng jié zhǐ shí jiān jīn tiān xià wǔ， tū fā shè bèi gù zhàng kě yǐ yán hòu yī tiān tí jiāo。','Hạn nộp bình thường là chiều nay, nhưng nếu sự cố thiết bị bất ngờ thì có thể gia hạn thêm một ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_05','V816','阮明',5,'我今天通宵重新撰写，明天上午一定完整上交定稿。','wǒ jīn tiān tōng xiāo chóng xīn zhuàn xiě， míng tiān shàng wǔ yí dìng wán zhěng shàng jiāo dìng gǎo。','Em sẽ thức xuyên đêm nay viết lại, chắc chắn sáng mai nộp đủ bản hoàn chỉnh cho thầy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_06','V816','李老师',6,'下次重要作业记得云端备份，避免设备故障丢失全部文稿。','xià cì zhòng yào zuò yè jì de yún duān bèi fèn， bì miǎn shè bèi gù zhàng diū shī quán bù wén gǎo。','Lần sau làm bài quan trọng nhớ sao lưu trên cloud, kẻo thiết bị hỏng là mất trắng cả bài đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_07','V816','阮明',7,'感谢老师通融延后提交，之后一定养成备份文件的习惯。','gǎn xiè lǎo shī tōng róng yán hòu tí jiāo， zhī hòu yí dìng yǎng chéng bèi fèn wén jiàn de xí guàn。','Em cảm ơn thầy đã thông cảm cho gia hạn, sau này em sẽ tập thói quen sao lưu file cẩn thận.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT817','SHT2','分不清直接引用、间接转述，找助教讲解论文写作规范',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V817','SIT817','P1','suon_se','tuy_y',NULL,'学术写作严格区分直接引用与间接转述，大段无标注摘抄会判定抄袭，大幅拉高查重重复率。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_01','V817','阮明',1,'学长，写论文分不清直接引用和间接转述，很容易查重超标。','xué zhǎng， xiě lùn wén fēn bù qīng zhí jiē yǐn yòng hé jiàn jiē zhuǎn shù， hěn róng yì chá zhòng chāo biāo。','Anh ơi, viết luận văn em cứ lẫn lộn giữa trích dẫn trực tiếp với diễn giải gián tiếp, dễ bị vượt tỷ lệ trùng lặp lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_02','V817','张学长',2,'直接引用加引号标注页码，篇幅不能过长；转述改写句式无需引号。','zhí jiē yǐn yòng jiā yǐn hào biāo zhù yè mǎ， piān fú bù néng guò cháng； zhuǎn shù gǎi xiě jù shì wú xū yǐn hào。','Trích dẫn trực tiếp thì cho vào ngoặc kép và ghi số trang, không được dài quá; còn diễn giải thì viết lại theo câu chữ của mình, không cần ngoặc kép.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_03','V817','阮明',3,'大段文献观点只能全部改写转述，不能连续直接摘抄原文对吧？','dà duàn wén xiàn guān diǎn zhǐ néng quán bù gǎi xiě zhuǎn shù， bù néng lián xù zhí jiē zhāi chāo yuán wén duì ba？','Vậy những đoạn quan điểm tài liệu dài thì chỉ được diễn giải lại hết, không được chép nguyên văn liên tục đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_04','V817','张学长',4,'单次直接引用不能超过三行，长观点必须拆分转述融合自己分析。','dān cì zhí jiē yǐn yòng bù néng chāo guò sān xíng， zhǎng guān diǎn bì xū chāi fēn zhuǎn shù róng hé zì jǐ fēn xī。','Đúng rồi, mỗi lần trích dẫn trực tiếp không được quá ba dòng, quan điểm dài phải tách ra diễn giải kết hợp với phân tích của bản thân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_05','V817','阮明',5,'我拿一段自己写的文字，麻烦你标出哪里引用格式出错。','wǒ ná yī duàn zì jǐ xiě de wén zì， má fán nǐ biāo chū nǎ lǐ yǐn yòng gé shì chū cuò。','Em có một đoạn tự viết, phiền anh chỉ giúp em chỗ nào format trích dẫn bị sai với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_06','V817','张学长',6,'没问题，逐句给你修改示范，方便你之后独立写作。','méi wèn tí， zhú jù gěi nǐ xiū gǎi shì fàn， fāng biàn nǐ zhī hòu dú lì xiě zuò。','Không vấn đề gì, để anh sửa mẫu từng câu cho em, để lần sau em tự viết được luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_07','V817','阮明',7,'听完示范清晰很多，不会再出现引用违规问题。','tīng wán shì fàn qīng xī hěn duō， bú huì zài chū xiàn yǐn yòng wéi guī wèn tí。','Nghe anh chỉ xong em rõ ràng hơn nhiều rồi, chắc không còn bị lỗi trích dẫn nữa đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT818','SHT2','询问期末课程论文字数下限、允许浮动范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V818','SIT818','P1','suon_se','ban_chinh_thuc',NULL,'课程论文、毕业论文有硬性最低正文字数要求，篇幅不足会被判定内容单薄，大幅扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_01','V818','阮明',1,'老师，期末课程论文要求最低字数五千字，上下浮动多少算合格？','lǎo shī， qī mò kè chéng lùn wén yāo qiú zuì dī zì shù wǔ qiān zì， shàng xià fú dòng duō shǎo suàn hé gé？','Thầy ơi, tiểu luận cuối kỳ yêu cầu tối thiểu năm nghìn chữ, dao động lên xuống bao nhiêu thì vẫn được tính đạt ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_02','V818','李老师',2,'正文五千字不含摘要参考文献，上下浮动五百字以内都可接受哦。','zhèng wén wǔ qiān zì bù hán zhāi yào cān kǎo wén xiàn， shàng xià fú dòng wǔ bǎi zì yǐ nèi dōu kě jiē shòu ó。','Phần thân bài năm nghìn chữ không tính tóm tắt và tài liệu tham khảo, dao động trong khoảng năm trăm chữ là chấp nhận được nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_03','V818','阮明',3,'字数不足四千五，会直接扣除论文基础分数吗？','zì shù bù zú sì qiān wǔ， huì zhí jiē kòu chú lùn wén jī chǔ fēn shù ma？','Nếu số chữ không đủ bốn nghìn năm trăm thì có bị trừ thẳng điểm cơ bản của bài không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_04','V818','李老师',4,'低于四千五会判定内容单薄，基础分直接减半。','dī yú sì qiān wǔ huì pàn dìng nèi róng dān bó， jī chǔ fēn zhí jiē jiǎn bàn。','Dưới bốn nghìn năm trăm chữ sẽ bị coi là nội dung sơ sài, điểm cơ bản sẽ bị trừ ngay một nửa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_05','V818','阮明',5,'图表、注释文字算不算入正文字数统计？','tú biǎo、 zhù shì wén zì suàn bù suàn rù zhèng wén zì shù tǒng jì？','Vậy hình ảnh, bảng biểu, chú thích có tính vào số chữ thân bài không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_06','V818','李老师',6,'图表说明、页下注释不计入，仅主体论述段落统计字数。','tú biǎo shuō míng、 yè xià zhù shì bù jì rù， jǐn zhǔ tǐ lùn shù duàn luò tǒng jì zì shù。','Chú thích hình bảng, chú thích cuối trang không tính, chỉ tính số chữ ở các đoạn văn luận điểm chính thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_07','V818','阮明',7,'我控制正文五千字左右，保证内容完整不缺篇幅。','wǒ kòng zhì zhèng wén wǔ qiān zì zuǒ yòu， bǎo zhèng nèi róng wán zhěng bù quē piān fú。','Vậy em sẽ khống chế thân bài khoảng năm nghìn chữ, đảm bảo nội dung đầy đủ chứ không thiếu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT819','SHT2','论文提交系统上传失败，咨询学院教务线上补交渠道',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V819','SIT819','P1','twist','ban_chinh_thuc',NULL,'课程、毕业论文线上提交系统有固定截止时间与文件格式、大小限制，超时通道自动关闭不再受理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_01','V819','阮明',1,'老师，论文线上提交系统上传文档一直提示失败，无法完成提交。','lǎo shī， lùn wén xiàn shàng tí jiāo xì tǒng shàng chuán wén dàng yì zhí tí shì shī bài， wú fǎ wán chéng tí jiāo。','Thầy ơi, em cứ tải file lên hệ thống nộp bài trực tuyến là báo lỗi thất bại, không nộp được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_02','V819','教务老师',2,'大概率文档内存过大、格式不是PDF，系统仅支持PDF格式上传嘛。','dà gài lǜ wén dàng nèi cún guò dà、 gé shì bú shì PDF， xì tǒng jǐn zhī chí PDF gé shì shàng chuán ma。','Chắc là dung lượng file quá lớn hoặc không phải định dạng PDF, hệ thống chỉ nhận file PDF thôi đấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_03','V819','阮明',3,'我原本是Word文档，直接转换PDF之后文件大小超系统限制。','wǒ yuán běn shì Word wén dàng， zhí jiē zhuǎn huàn PDF zhī hòu wén jiàn dà xiǎo chāo xì tǒng xiàn zhì。','Ban đầu em làm file Word, chuyển sang PDF xong thì dung lượng lại vượt giới hạn hệ thống.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_04','V819','教务老师',4,'压缩PDF文件降低分辨率，缩小内存后重新进入系统提交。','yā suō PDF wén jiàn jiàng dī fēn biàn lǜ， suō xiǎo nèi cún hòu chóng xīn jìn rù xì tǒng tí jiāo。','Em nén file PDF lại, giảm độ phân giải xuống cho nhẹ dung lượng rồi vào hệ thống nộp lại thử xem.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_05','V819','阮明',5,'今天是提交截止日，压缩完成后错过零点还能补交吗？','jīn tiān shì tí jiāo jié zhǐ rì， yā suō wán chéng hòu cuò guò líng diǎn hái néng bǔ jiāo ma？','Hôm nay là hạn chót nộp bài, nếu nén xong mà lỡ qua giờ đúng nửa đêm thì còn nộp bổ sung được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_06','V819','教务老师',6,'系统零点关闭通道，今晚二十三点五十九分前必须上传成功。','xì tǒng líng diǎn guān bì tōng dào， jīn wǎn èr shí sān diǎn wǔ shí jiǔ fēn qián bì xū shàng chuán chéng gōng。','Hệ thống đóng cổng đúng lúc nửa đêm, tối nay bắt buộc phải tải lên thành công trước 23 giờ 59 phút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_07','V819','阮明',7,'我立刻压缩文档，赶在通道关闭前完成论文提交。','wǒ lì kè yā suō wén dàng， gǎn zài tōng dào guān bì qián wán chéng lùn wén tí jiāo。','Vậy em nén file ngay bây giờ, cố gắng nộp xong tiểu luận trước khi cổng đóng.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT820','SHT3','想引用网络自媒体资料，咨询老师是否符合学术规范',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V820','SIT820','P1','that_bai_nhe','ban_chinh_thuc',NULL,'自媒体、短视频平台内容不具备学术权威性，高校论文不允许单独以此作为核心论证依据。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_01','V820','阮明',1,'老师，论文里想引用自媒体公众号文章的数据作为论据可以吗？','lǎo shī， lùn wén lǐ xiǎng yǐn yòng zì méi tǐ gōng zhòng hào wén zhāng de shù jù zuò wéi lùn jù kě yǐ ma？','Thầy ơi, em muốn trích dẫn số liệu từ bài viết trên trang tự truyền thông (fanpage) vào luận văn làm luận cứ có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_02','V820','李老师',2,'自媒体无正规学术审核，仅能作为辅助参考，不能当作核心论据。','zì méi tǐ wú zhèng guī xué shù shěn hé， jǐn néng zuò wéi fǔ zhù cān kǎo， bù néng dàng zuò hé xīn lùn jù。','Nội dung tự truyền thông không qua thẩm định học thuật chính quy, chỉ dùng làm tham khảo phụ thôi, không thể dùng làm luận cứ chính được đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_03','V820','阮明',3,'如果数据来源只有自媒体，有没有办法合规写入论文内容？','rú guǒ shù jù lái yuán zhǐ yǒu zì méi tǐ， yǒu méi yǒu bàn fǎ hé guī xiě rù lùn wén nèi róng？','Nếu nguồn dữ liệu chỉ có ở trang tự truyền thông thì có cách nào đưa vào luận văn cho hợp lệ không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_04','V820','李老师',4,'必须搭配官方期刊、统计年鉴佐证，单独自媒体内容不予认可嘛。','bì xū dā pèi guān fāng qī kān、 tǒng jì nián jiàn zuǒ zhèng， dān dú zì méi tǐ nèi róng bù yǔ rèn kě ma。','Bắt buộc phải kèm theo tạp chí chính thống, niên giám thống kê để chứng minh, chứ chỉ dùng riêng nội dung tự truyền thông thì không được công nhận đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_05','V820','阮明',5,'那我放弃自媒体素材，重新检索官方行业报告替换论据。','nà wǒ fàng qì zì méi tǐ sù cái， chóng xīn jiǎn suǒ guān fāng háng yè bào gào tì huàn lùn jù。','Vậy em bỏ tư liệu tự truyền thông đi, tìm lại báo cáo ngành chính thức để thay thế luận cứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_06','V820','李老师',6,'学术论文优先采用官方、期刊、专著类权威文献资料。','xué shù lùn wén yōu xiān cǎi yòng guān fāng、 qī kān、 zhuān zhù lèi quán wēi wén xiàn zī liào。','Luận văn học thuật nên ưu tiên dùng tài liệu chính thống, tạp chí khoa học, sách chuyên khảo có uy tín.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_07','V820','阮明',7,'我重新查找正规数据源，保证论文引用符合学术标准。','wǒ chóng xīn chá zhǎo zhèng guī shù jù yuán， bǎo zhèng lùn wén yǐn yòng fú hé xué shù biāo zhǔn。','Vậy em sẽ tìm lại nguồn dữ liệu chính quy, đảm bảo trích dẫn trong luận văn đúng chuẩn học thuật.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT821','SHT3','咨询老师期末复习重点、必考章节范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V821','SIT821','P1','suon_se','ban_chinh_thuc',NULL,'期末考前老师会划定大致复习范围，缩小复习体量，但不会直接透露原题，依靠学生自主背诵理解。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_01','V821','阮明',1,'老师，距离期末考还有两周，想咨询课程核心复习重点章节。','lǎo shī， jù lí qī mò kǎo hái yǒu liǎng zhōu， xiǎng zī xún kè chéng hé xīn fù xí zhòng diǎn zhāng jié。','Thầy ơi, còn hai tuần nữa là thi cuối kỳ, em muốn hỏi những chương trọng tâm cần ôn tập của môn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_02','V821','李老师',2,'课本中间四个单元是试卷主要考点，首尾单元仅少量选择题哦。','kè běn zhōng jiān sì gè dān yuán shì shì juàn zhǔ yào kǎo diǎn， shǒu wěi dān yuán jǐn shǎo liàng xuǎn zé tí ó。','Bốn đơn vị bài ở giữa sách là trọng tâm chính của đề thi, các đơn vị đầu và cuối chỉ ra ít câu trắc nghiệm thôi nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_03','V821','阮明',3,'课后拓展阅读书目、课外补充案例会不会出大题？','kè hòu tuò zhǎn yuè dú shū mù、 kè wài bǔ chōng àn lì huì bú huì chū dà tí？','Vậy sách đọc mở rộng và các case study bổ sung ngoài giờ học có ra trong câu tự luận lớn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_04','V821','李老师',4,'大题全部来自课内课本与课堂例题，课外内容仅少量选择填空。','dà tí quán bù lái zì kè nèi kè běn yǔ kè táng lì tí， kè wài nèi róng jǐn shǎo liàng xuǎn zé tián kòng。','Câu tự luận lớn đều lấy từ sách giáo trình và ví dụ trên lớp, phần ngoài chương trình chỉ ra ít câu trắc nghiệm hoặc điền khuyết thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_05','V821','阮明',5,'名词解释、论述题分别对应课本哪一部分内容？','míng cí jiě shì、 lùn shù tí fēn bié duì yìng kè běn nǎ yī bù fèn nèi róng？','Vậy phần giải thích thuật ngữ và phần tự luận tương ứng với nội dung nào trong sách ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_06','V821','李老师',6,'名词解释每单元课后词汇，论述题是课堂反复讲解的核心观点。','míng cí jiě shì měi dān yuán kè hòu cí huì， lùn shù tí shì kè táng fǎn fù jiǎng jiě de hé xīn guān diǎn。','Giải thích thuật ngữ thì lấy từ vựng cuối mỗi đơn vị bài, còn tự luận là những quan điểm cốt lõi được giảng đi giảng lại trên lớp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_07','V821','阮明',7,'我优先重点复习核心单元，针对性背诵大题考点。','wǒ yōu xiān zhòng diǎn fù xí hé xīn dān yuán， zhēn duì xìng bèi sòng dà tí kǎo diǎn。','Vậy em sẽ ưu tiên ôn kỹ các đơn vị trọng tâm, học thuộc có định hướng cho các câu tự luận.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT822','SHT3','错过随堂小测，询问老师能否安排补测',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V822','SIT822','P1','twist','ban_chinh_thuc',NULL,'因病、公事请假缺测可凭证明补测，无故缺考无补测机会，直接扣除对应平时分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_01','V822','阮明',1,'老师，上周随堂小测我生病请假，没能到场完成测试。','lǎo shī， shàng zhōu suí táng xiǎo cè wǒ shēng bìng qǐng jià， méi néng dào chǎng wán chéng cè shì。','Thầy ơi, tuần trước em bị ốm phải xin nghỉ nên không tham gia bài kiểm tra trên lớp được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_02','V822','李老师',2,'有医院病假证明备案的学生，可以统一参加期末前集中补测。','yǒu yī yuàn bìng jià zhèng míng bèi àn de xué shēng， kě yǐ tǒng yī cān jiā qī mò qián jí zhōng bǔ cè。','Những sinh viên có giấy xác nhận nghỉ ốm của bệnh viện đăng ký lại thì có thể tham gia đợt kiểm tra bù tập trung trước kỳ thi cuối kỳ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_03','V822','阮明',3,'我保留完整医院病历单据，今天带来给您登记备案可以吗？','wǒ bǎo liú wán zhěng yī yuàn bìng lì dān jù， jīn tiān dài lái gěi nín dēng jì bèi àn kě yǐ ma？','Em còn giữ đầy đủ hồ sơ bệnh án của bệnh viện, hôm nay em mang tới để thầy đăng ký được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_04','V822','李老师',4,'病历登记截止本周四，周四之后不再受理补测报名嘛。','bìng lì dēng jì jié zhǐ běn zhōu sì， zhōu sì zhī hòu bù zài shòu lǐ bǔ cè bào míng ma。','Hạn đăng ký hồ sơ bệnh án là hết thứ Năm tuần này, sau thứ Năm sẽ không nhận đăng ký kiểm tra bù nữa đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_05','V822','阮明',5,'补测试卷难度、分值和正常随堂小测完全一致吗？','bǔ cè shì juàn nán dù、 fēn zhí hé zhèng cháng suí táng xiǎo cè wán quán yí zhì ma？','Vậy đề kiểm tra bù độ khó và thang điểm có giống hệt bài kiểm tra trên lớp bình thường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_06','V822','李老师',6,'题型、分值标准相同，只是作答时间缩短十分钟。','tí xíng、 fēn zhí biāo zhǔn xiāng tóng， zhǐ shì zuò dá shí jiān suō duǎn shí fēn zhōng。','Dạng đề và thang điểm giống nhau, chỉ là thời gian làm bài rút ngắn mười phút thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_07','V822','阮明',7,'我今天上交病假单登记，按时参加统一补测。','wǒ jīn tiān shàng jiāo bìng jià dān dēng jì， àn shí cān jiā tǒng yī bǔ cè。','Vậy hôm nay em nộp giấy nghỉ ốm để đăng ký, rồi tham gia đúng giờ đợt kiểm tra bù tập trung.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT823','SHT3','期末挂科，咨询补考报名时间、复习范围',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V823','SIT823','P1','suon_se','chinh_thuc',NULL,'国内大学补考最高绩点60分，仅标记及格，无法参与奖学金评选，重修才能刷新分数。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_01','V823','阮明',1,'老师，这门专业课期末挂科，想咨询补考报名与复习范围。','lǎo shī， zhè mén zhuān yè kè qī mò guà kē， xiǎng zī xún bǔ kǎo bào míng yǔ fù xí fàn wéi。','Thưa thầy, môn chuyên ngành này em bị rớt trong kỳ thi cuối kỳ, em muốn hỏi về thời gian đăng ký thi lại và phạm vi ôn tập.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_02','V823','教务老师',2,'开学第一周线上系统开放补考报名，逾期视为自动放弃补考。','kāi xué dì yī zhōu xiàn shàng xì tǒng kāi fàng bǔ kǎo bào míng， yú qī shì wèi zì dòng fàng qì bǔ kǎo。','Tuần đầu tiên của học kỳ mới, hệ thống trực tuyến sẽ mở đăng ký thi lại, quá hạn sẽ coi như tự động từ bỏ quyền thi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_03','V823','阮明',3,'补考试卷考点和期末试卷范围一样，还是会更换全新章节？','bǔ kǎo shì juàn kǎo diǎn hé qī mò shì juàn fàn wéi yī yàng， hái shì huì gēng huàn quán xīn zhāng jié？','Phạm vi kiến thức của đề thi lại có giống với đề thi cuối kỳ không, hay sẽ đổi sang những chương hoàn toàn mới ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_04','V823','教务老师',4,'考点范围完全相同，试卷题目全部重新出题，不会使用原卷。','kǎo diǎn fàn wéi wán quán xiāng tóng， shì juàn tí mù quán bù chóng xīn chū tí， bú huì shǐ yòng yuán juǎn。','Phạm vi kiến thức hoàn toàn giống nhau, nhưng đề thi sẽ được ra mới hoàn toàn, không dùng lại đề cũ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_05','V823','阮明',5,'补考及格即可拿到学分，补考分数会直接替代期末成绩吗？','bǔ kǎo jí gé jí kě ná dào xué fēn， bǔ kǎo fēn shù huì zhí jiē tì dài qī mò chéng jì ma？','Thi lại đạt điểm là được công nhận tín chỉ phải không ạ, và điểm thi lại có thay thế trực tiếp điểm cuối kỳ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_06','V823','教务老师',6,'补考最高记60分及格，无论考多高都不会计入高分。','bǔ kǎo zuì gāo jì 60 fēn jí gé， wú lùn kǎo duō gāo dōu bú huì jì rù gāo fēn。','Điểm thi lại tối đa chỉ được ghi nhận là 60 điểm đạt, dù thi cao đến đâu cũng không được tính điểm cao hơn mức đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_07','V823','阮明',7,'我暑假完整复习课本核心内容，开学顺利通过补考。','wǒ shǔ jià wán zhěng fù xí kè běn hé xīn nèi róng， kāi xué shùn lì tōng guò bǔ kǎo。','Vậy hè này em sẽ ôn tập kỹ nội dung trọng tâm trong sách, để khai giảng là thi lại đạt luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT824','SHT3','补考仍未通过，咨询重修选课流程与缴费标准',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V824','SIT824','P1','that_bai_nhe','chinh_thuc',NULL,'补考不及格必须重修该门课程，按学分收取重修费用，全部考核达标才能拿到对应学分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_01','V824','阮明',1,'老师，补考依旧没有及格，想咨询课程重修办理流程。','lǎo shī， bǔ kǎo yī jiù méi yǒu jí gé， xiǎng zī xún kè chéng chóng xiū bàn lǐ liú chéng。','Thưa thầy/cô, em thi lại vẫn chưa đạt, em muốn hỏi về quy trình đăng ký học lại ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_02','V824','教务老师',2,'下一学期选课周期，线上系统勾选重修课程，缴纳重修学分费。','xià yī xué qī xuǎn kè zhōu qī， xiàn shàng xì tǒng gōu xuǎn chóng xiū kè chéng， jiǎo nà chóng xiū xué fēn fèi。','Vào đợt đăng ký học phần của học kỳ sau, em vào hệ thống trực tuyến chọn học lại và đóng học phí học lại là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_03','V824','阮明',3,'重修需要全程跟班上课、完成全部平时作业与课堂小测吗？','chóng xiū xū yào quán chéng gēn bān shàng kè、 wán chéng quán bù píng shí zuò yè yǔ kè táng xiǎo cè ma？','Em học lại có cần theo học đầy đủ cùng lớp, hoàn thành hết bài tập thường xuyên và kiểm tra trên lớp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_04','V824','教务老师',4,'是的，重修完整复刻正常课程考核规则，出勤、作业、考试全部计分嘛。','shì de， chóng xiū wán zhěng fù kè zhèng cháng kè chéng kǎo hé guī zé， chū qín、 zuò yè、 kǎo shì quán bù jì fēn ma。','Đúng vậy, học lại áp dụng đầy đủ quy chế đánh giá như học bình thường, điểm danh, bài tập, thi cử đều được tính điểm đấy.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_05','V824','阮明',5,'一学分重修收费标准多少，一门完整课程一共几学分？','yī xué fēn chóng xiū shōu fèi biāo zhǔn duō shǎo， yī mén wán zhěng kè chéng yī gòng jǐ xué fēn？','Học phí học lại tính theo mỗi tín chỉ là bao nhiêu, và môn này tổng cộng bao nhiêu tín chỉ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_06','V824','教务老师',6,'每学分一百元，本课程四学分，一次性缴纳四百元重修费。','měi xué fēn yì bǎi yuán， běn kè chéng sì xué fēn， yí cì xìng jiǎo nà sì bǎi yuán chóng xiū fèi。','Mỗi tín chỉ một trăm nghìn, môn này bốn tín chỉ, đóng một lần bốn trăm nghìn tiền học lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_07','V824','阮明',7,'我记下选课时间，下一学期按时报名重修认真学习。','wǒ jì xià xuǎn kè shí jiān， xià yī xué qī àn shí bào míng chóng xiū rèn zhēn xué xí。','Em đã ghi nhớ thời gian đăng ký, học kỳ sau em sẽ đăng ký học lại đúng hạn và học nghiêm túc.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT825','SHT3','询问考场允许携带的文具，禁止带入物品清单',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V825','SIT825','P1','suon_se','ban_chinh_thuc',NULL,'国内标准化考场严格管控随身物品，电子设备、纸质资料一律禁止带入，草稿纸统一发放回收。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_01','V825','阮明',1,'老师，期末考场允许携带哪些文具，有物品禁止带入考场吗？','lǎo shī， qī mò kǎo chǎng yǔn xǔ xié dài nǎ xiē wén jù， yǒu wù pǐn jìn zhǐ dài rù kǎo chǎng ma？','Thưa thầy/cô, phòng thi cuối kỳ cho phép mang những dụng cụ học tập nào, có vật gì bị cấm mang vào không ạ?',NULL);
